                                    if (player.storage.zhishuc3d8_mark_wei == card.suit && target.group != 'wei') return false;
                                    if (player.storage.zhishuc3d8_mark_shu == card.suit && target.group != 'shu') return false;
                                    if (player.storage.zhishuc3d8_mark_wu == card.suit && target.group != 'wu') return false;
